# Initialize an empty list to store tasks
tasks = []

def add_task():
    """Add a new task to the to-do list."""
    global tasks
    task = input("Enter a task (or type 'done' to complete): ")
    if task.lower() == "done":
        tasks.append(task)
    else:
        tasks.append(f"Task {len(tasks) + 1}: {task}")

def remove_task():
    """Remove a task from the to-do list."""
    global tasks
    task_number = int(input("Enter the number of the task to remove: ")) - 1
    if 0 <= task_number < len(tasks):
        tasks.pop(task_number)

def display_tasks():
    """Display all tasks in the to-do list."""
    global tasks
    print("\n".join(tasks))

def manage_to_do_list():
    """The main function to manage the to-do list."""
    while True:
        print("1. Add a task")
        print("2. Remove a task")
        print("3. Display tasks")
        print("4. Exit")

        choice = int(input("Enter your choice: "))

        if choice == 1:
            add_task()
        elif choice == 2:
            remove_task()
        elif choice == 3:
            display_tasks()
        elif choice == 4:
            print("Exiting the to-do list manager...")
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    manage_to_do_list()
```

This program defines three functions: `add_task()`, `remove_task()`, and `display_tasks()`. The `manage_to_do_list()` function is the main function that handles user input and calls the other functions as needed. The `if __name__ == "__main__":` block ensures that the functions are called when the script is run directly, and not when it's imported as a module.
